constexpr int calculate(int a, int b) {
    return a * b + 1;
}

// Compile-Time Evaluation (Optimization/Elimination)
constexpr int OPT_VAL = calculate(10, 5);
// Array size requires compile-time constant:
int arr[OPT_VAL];

int runtime_input();

// Runtime Evaluation (Fallback)
void process_data() {
    int x = runtime_input();
    // Inputs unknown at compile time: evaluated at runtime
    int RT_VAL = calculate(x, 2);
}
